use std::path::Path;

use super::{Refused, checked};

/// A digest, as a hash names one.
const HEX: &str = "8f4ab0e8ea1d1e1ad4c8b0e5f2b7f9d9a3a8c1d4e7f6a5b4c3d2e1f0a9b8c7d6";

#[test]
fn an_exported_lock_and_a_wheel_of_this_tree_are_taken_as_pip_reads_them() {
    let text = format!(
        "# This file was autogenerated by uv via the following command:\n\
         #    uv export --frozen --no-default-groups --no-emit-project --format requirements-txt\n\
         annotated-types==0.7.0 \\\n    --hash=sha256:{HEX} \\\n    --hash=sha256:{HEX}\n    \
         # via pydantic\n\
         pyarrow==21.0.0 ; sys_platform == 'linux' \\\n    --hash=sha256:{HEX}\n\
         pydantic[email] == 2.11.7 --hash sha256:{HEX}\n\
         \n\
         rdlt @ file:///home/someone/rdlt/target/wheels/rdlt-0.0.0-cp311-abi3-manylinux_2_28_x86_64.whl --hash=sha256:{HEX}\n"
    );
    let lines = checked(&text, Path::new("/requirements")).unwrap();
    assert_eq!(
        lines,
        [
            format!("annotated-types==0.7.0 --hash=sha256:{HEX} --hash=sha256:{HEX}"),
            format!("pyarrow==21.0.0 ; sys_platform == \"linux\" --hash=sha256:{HEX}"),
            format!("pydantic[email]==2.11.7 --hash=sha256:{HEX}"),
            format!(
                "rdlt @ file:///home/someone/rdlt/target/wheels/\
                 rdlt-0.0.0-cp311-abi3-manylinux_2_28_x86_64.whl --hash=sha256:{HEX}"
            ),
        ]
    );
}

#[test]
fn where_packages_are_found_is_taken_a_relative_path_from_the_file_s_directory() {
    let text = "--index-url https://mirror.example/simple\n-i=https://other.example/simple\n\
                --extra-index-url=https://extra.example/simple\n--find-links wheels\n\
                -f /absolute/wheels\n--no-index\n";
    let lines = checked(text, Path::new("/requirements")).unwrap();
    assert_eq!(
        lines,
        [
            "--index-url 'https://mirror.example/simple'",
            "--index-url 'https://other.example/simple'",
            "--extra-index-url 'https://extra.example/simple'",
            "--find-links '/requirements/wheels'",
            "--find-links '/absolute/wheels'",
            "--no-index",
        ]
    );
}

#[test]
fn every_line_that_could_have_pip_build_from_source_or_read_elsewhere_is_refused_by_its_number() {
    let hash = format!("--hash=sha256:{HEX}");
    for (line, refused) in [
        (
            "--index-url https://${TOKEN}@mirror.example/simple".to_owned(),
            1,
        ),
        (format!("evil==1.0 {hash}\n-r other.txt"), 2),
        ("-c constraints.txt".to_owned(), 1),
        ("-e .".to_owned(), 1),
        ("--no-binary :all:".to_owned(), 1),
        ("--only-binary :none:".to_owned(), 1),
        ("--trusted-host mirror.example".to_owned(), 1),
        ("--pre".to_owned(), 1),
        ("--index-url".to_owned(), 1),
        ("--index-url=".to_owned(), 1),
        ("--index-url a b".to_owned(), 1),
        ("--find-links \"/with quotes\"".to_owned(), 1),
        (format!("evil @ file:///wheels/evil-1.0.tar.gz {hash}"), 1),
        (format!("evil @ git+https://example.com/evil.whl {hash}"), 1),
        (
            format!("evil @ https://example.com/evil-1.0.tar.gz#egg=evil.whl {hash}"),
            1,
        ),
        (format!("evil>=1.0 {hash}"), 1),
        (format!("evil==1.* {hash}"), 1),
        (format!("evil===1.0 {hash}"), 1),
        (format!("evil==1.0,>=0.5 {hash}"), 1),
        (format!("evil {hash}"), 1),
        (format!("-evil==1.0 {hash}"), 1),
        (format!("evil[x==1.0 {hash}"), 1),
        ("evil==1.0".to_owned(), 1),
        (format!("evil==1.0 --hash=md5:{HEX}"), 1),
        ("evil==1.0 --hash=sha256:not-hex".to_owned(), 1),
        ("evil==1.0 --hash".to_owned(), 1),
        (format!("evil==1.0 --pre {hash}"), 1),
        (format!("evil==1.0 ; {hash}"), 1),
        (
            format!("# first\n\nevil==1.0 \\\n {hash} \\\n --no-binary :all:"),
            3,
        ),
    ] {
        let found = checked(&line, Path::new("/requirements"));
        assert!(
            matches!(found, Err((number, _)) if number == refused),
            "{line:?}: {found:?}"
        );
    }
}

#[test]
fn a_comment_ends_a_line_only_where_whitespace_comes_before_it() {
    let text = format!(
        "wheel @ https://example.com/wheel-1.0-py3-none-any.whl#sha256={HEX} --hash=sha256:{HEX} # a note\n"
    );
    let lines = checked(&text, Path::new("/requirements")).unwrap();
    assert_eq!(
        lines,
        [format!(
            "wheel @ https://example.com/wheel-1.0-py3-none-any.whl#sha256={HEX} --hash=sha256:{HEX}"
        )]
    );
}

#[test]
fn a_line_continued_at_the_end_of_the_file_is_taken() {
    let text = format!("wheel==1.0 \\\n --hash=sha256:{HEX} \\");
    let lines = checked(&text, Path::new("/requirements")).unwrap();
    assert_eq!(lines, [format!("wheel==1.0 --hash=sha256:{HEX}")]);
}

/// The characters Python's `str.splitlines`, which pip reads a requirements file with, ends a line
/// at, but for `\n`.
const BREAKS: [char; 9] = [
    '\r', '\u{b}', '\u{c}', '\u{1c}', '\u{1d}', '\u{1e}', '\u{85}', '\u{2028}', '\u{2029}',
];

/// `text` broken into lines as Python's `str.splitlines` breaks it.
fn python_lines(text: &str) -> Vec<String> {
    let text = text.replace("\r\n", "\n");
    text.split(|c| c == '\n' || BREAKS.contains(&c))
        .map(str::to_owned)
        .collect()
}

#[test]
fn a_character_that_could_end_a_line_for_pip_is_refused_in_markers_and_in_urls() {
    let hash = format!("--hash=sha256:{HEX}");
    for break_ in BREAKS {
        for line in [
            format!("ok==1.0 ; python_version>\"0\"{break_}--no-binary :all: {hash}"),
            format!("ok @ https://example.com/ok{break_}-1.0-py3-none-any.whl {hash}"),
            format!("# a note{break_}--no-binary :all:\nok==1.0 {hash}"),
        ] {
            let found = checked(&line, Path::new("/requirements"));
            assert_eq!(found, Err((1, Refused::Character(break_))), "{line:?}");
        }
    }
    for refused in ['\u{0}', '\u{7f}', 'é', '\u{feff}'] {
        let line = format!("ok==1.0 {hash}\nother==1.0 ; os_name == 'x{refused}' {hash}");
        let found = checked(&line, Path::new("/requirements"));
        assert_eq!(found, Err((2, Refused::Character(refused))), "{line:?}");
    }
}

#[test]
fn a_file_of_windows_line_ends_or_a_byte_order_mark_is_taken() {
    let text =
        format!("\u{feff}one==1.0 \\\r\n --hash=sha256:{HEX}\r\ntwo==2.0\t--hash=sha256:{HEX}\r\n");
    let lines = checked(&text, Path::new("/requirements")).unwrap();
    let expected = [
        format!("one==1.0 --hash=sha256:{HEX}"),
        format!("two==2.0 --hash=sha256:{HEX}"),
    ];
    assert_eq!(lines, expected);
}

#[test]
fn what_pip_is_given_breaks_into_the_lines_rdlt_checked_and_no_more() {
    let hash = format!("--hash=sha256:{HEX}");
    let taken = format!(
        "--index-url https://mirror.example/simple\n--find-links wheels\n--no-index\n\
         one[a, b] == 1.0+local.2 ; python_version >= '3.11' and sys_platform != \"win32\" {hash}\n\
         two @ https://user:x@example.com/two-1.0-py3-none-any.whl#sha256={HEX} {hash}\n\
         three @ file:///with%20space/three-1.0-py3-none-any.whl {hash} --hash sha256:{HEX}\n"
    );
    let lines = checked(&taken, Path::new("/requirements dir")).unwrap();
    assert_eq!(lines.len(), 6);
    for line in &lines {
        assert_eq!(python_lines(line), std::slice::from_ref(line), "{line:?}");
        let printable = line.bytes().all(|byte| (b' '..=b'~').contains(&byte));
        assert!(printable, "{line:?}");
        // pip splits a line at its spaces, its options from the first word that starts with `-`.
        let words: Vec<&str> = line.split(' ').collect();
        let first = words.iter().position(|word| word.starts_with('-')).unwrap();
        if first == 0 && words.len() > 1 {
            // An option's line, split as a shell splits it: its value is all within one quote.
            let quoted = line.split_once(' ').unwrap().1;
            let inner = quoted
                .strip_prefix('\'')
                .and_then(|quoted| quoted.strip_suffix('\''));
            assert!(inner.is_some_and(|inner| !inner.contains('\'')), "{line:?}");
        } else if first > 0 {
            let options = &words[first..];
            let hashes = options
                .iter()
                .all(|word| word.starts_with("--hash=sha256:"));
            assert!(hashes, "{line:?}");
        }
    }
    assert_eq!(python_lines(&lines.join("\n")), lines);
}

#[test]
fn a_part_outside_its_own_characters_is_refused() {
    let hash = format!("--hash=sha256:{HEX}");
    for (line, refused) in [
        (format!("evil==1.0 --hash=sha256:{HEX}0"), 1),
        (format!("evil==1.0 --hash=sha384:{HEX}"), 1),
        (format!("evil==1.0 --hash=sha512:{HEX}{}", &HEX[..32]), 1),
        (format!("evil==1.0 --hash=sha256:{HEX}{}", &HEX[..32]), 1),
        (format!("evil==1.0 --hash=sha1:{}", &HEX[..40]), 1),
        (format!("evil==1.0 ; os_name == '${{X}}' {hash}"), 1),
        (format!("evil==1.0 ; os_name == a,b {hash}"), 1),
        (format!("evil==1.0 ; python_version == 3.* {hash}"), 1),
        (format!("evil==1.0 ; os_name == {{x}} {hash}"), 1),
        (format!("evil==1.0 ; os_name == 'abc {hash}"), 1),
        (format!("evil==1.0 ; os_name == \"a' {hash}"), 1),
        (
            format!("evil @ https://example.com/e\"vil-1.0-py3-none-any.whl {hash}"),
            1,
        ),
        (
            format!("evil @ https://example.com/e{{v}}il-1.0-py3-none-any.whl {hash}"),
            1,
        ),
        (
            format!("evil @ https://example.com/e\\vil-1.0-py3-none-any.whl {hash}"),
            1,
        ),
        ("--find-links https://example.com/{x}".to_owned(), 1),
        (format!("ok[x y]==1.0 {hash}"), 1),
        (format!("o!k[x]==1.0 {hash}"), 1),
    ] {
        let found = checked(&line, Path::new("/requirements"));
        assert!(
            matches!(found, Err((number, _)) if number == refused),
            "{line:?}: {found:?}"
        );
    }
}

#[test]
fn a_relative_place_in_a_directory_pip_would_read_otherwise_is_refused() {
    for directory in ["/it's", "/zo\u{eb}", "/new\nline", "/a #b", "/${X}"] {
        let found = checked("--find-links wheels", Path::new(directory));
        assert!(matches!(found, Err((1, _))), "{directory:?}: {found:?}");
    }
    for directory in ["/with space", "/back\\slash", "/quoted\""] {
        let found = checked("--find-links wheels", Path::new(directory));
        let written = format!("--find-links '{directory}/wheels'");
        assert_eq!(found, Ok(vec![written]), "{directory:?}");
    }
}

#[test]
fn a_refusal_says_why_and_names_the_character_it_met() {
    assert_eq!(Refused::Line("why").to_string(), "why");
    let said = Refused::Character('\u{1c}').to_string();
    assert!(said.contains("'\\u{1c}'"), "{said}");
}

#[test]
fn a_hash_of_each_sha_2_length_is_taken() {
    let (sha384, sha512) = (format!("{HEX}{}", &HEX[..32]), format!("{HEX}{HEX}"));
    let text = format!(
        "one==1.0 --hash=sha384:{sha384} --hash=sha512:{sha512}\n\
         two==2.0 ; os_name == 'a,b' and python_version == \"3.*\" --hash=sha256:{HEX}\n"
    );
    let lines = checked(&text, Path::new("/requirements")).unwrap();
    let expected = [
        format!("one==1.0 --hash=sha384:{sha384} --hash=sha512:{sha512}"),
        format!("two==2.0 ; os_name == \"a,b\" and python_version == \"3.*\" --hash=sha256:{HEX}"),
    ];
    assert_eq!(lines, expected);
}

#[test]
fn text_after_a_semicolon_is_never_an_option_of_pip_s() {
    let hash = format!("--hash=sha256:{HEX}");
    for line in [
        format!("planted==1.0;--no-binary=planted {hash}"),
        format!("planted==1.0 ;--no-binary=planted {hash}"),
        format!("planted==1.0 ; --no-binary=planted {hash}"),
        format!("x @ https://h.example/x-1-py3-none-any.whl;--no-binary=planted {hash}"),
        format!("planted==1.0 ; os_name == '--no-binary=planted' {hash}"),
        format!("planted==1.0 ; os_name == 'x' -x {hash}"),
        format!("three==3.0 ; platform_release == 'say \"{{x}}\", 1;' {hash}"),
    ] {
        let found = checked(&line, Path::new("/requirements"));
        assert!(matches!(found, Err((1, _))), "{line:?}: {found:?}");
    }
}

#[test]
fn a_version_pip_would_read_as_a_file_s_name_is_refused() {
    let hash = format!("--hash=sha256:{HEX}");
    for version in ["1.tar.gz", "1.zip", "1.whl", "1.0/x"] {
        let line = format!("foo=={version} {hash}");
        let found = checked(&line, Path::new("/requirements"));
        assert!(matches!(found, Err((1, _))), "{line:?}: {found:?}");
    }
}
